    adcs_vec3_t unit_vec;
    adcs_mat3_t weighted_outer_sum;
    double total_weight = 0.0;
    size_t i;

    // Failure output zero: initialize output matrix to zeros immediately
    for (size_t r = 0; r < 3; r++) {
        for (size_t c = 0; c < 3; c++) {
            information->m[r][c] = 0.0;
        }
    }

    // Boundary and failure handling: Null check
    if ((vectors == NULL) || (weights == NULL) || (information == NULL)) {
        return ADCS_E_NULL;
    }

    // Boundary and failure handling: Invalid count
    if ((count < 2U) || (count > 32U)) {
        return ADCS_E_RANGE;
    }

    // Initialize accumulator for weighted outer products
    for (size_t r = 0; r < 3; r++) {
        for (size_t c = 0; c < 3; c++) {
            weighted_outer_sum.m[r][c] = 0.0;
        }
    }

    // Process each observation
    for (i = 0; i < count; i++) {
        double w = weights[i];

        // Validate weight: must be finite and positive
        if ((!isfinite(w)) || (w <= 0.0)) {
            return ADCS_E_RANGE;
        }

        // Normalize vector: invalid vector (non-positive norm) -> ADCS_E_RANGE
        if (adcs_vec3_normalize(&vectors[i], ADCS_EPS_NORM, &unit_vec) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Compute outer product u_k * u_k^T and accumulate w_k * (u_k * u_k^T)
        // Since u*u^T is symmetric, we can compute directly
        double ux = unit_vec.x;
        double uy = unit_vec.y;
        double uz = unit_vec.z;
        double wx = w * ux;
        double wy = w * uy;
        double wz = w * uz;

        weighted_outer_sum.m[0][0] += wx * ux;
        weighted_outer_sum.m[0][1] += wx * uy;
        weighted_outer_sum.m[0][2] += wx * uz;

        weighted_outer_sum.m[1][0] += wy * ux;
        weighted_outer_sum.m[1][1] += wy * uy;
        weighted_outer_sum.m[1][2] += wy * uz;

        weighted_outer_sum.m[2][0] += wz * ux;
        weighted_outer_sum.m[2][1] += wz * uy;
        weighted_outer_sum.m[2][2] += wz * uz;

        total_weight += w;
    }

    // Calculate H = total_weight * I - sum(w_k * u_k * u_k^T)
    // This satisfies H = sum w_k (I - u_k u_k^T)

    // Diagonal elements
    information->m[0][0] = total_weight - weighted_outer_sum.m[0][0];
    information->m[1][1] = total_weight - weighted_outer_sum.m[1][1];
    information->m[2][2] = total_weight - weighted_outer_sum.m[2][2];

    // Off-diagonal elements (negative of accumulated outer products)
    information->m[0][1] = -weighted_outer_sum.m[0][1];
    information->m[0][2] = -weighted_outer_sum.m[0][2];
    information->m[1][0] = -weighted_outer_sum.m[1][0];
    information->m[1][2] = -weighted_outer_sum.m[1][2];
    information->m[2][0] = -weighted_outer_sum.m[2][0];
    information->m[2][1] = -weighted_outer_sum.m[2][1];

    return ADCS_OK;
}

