    // 1. Null checks
    if ((vectors == NULL) || (weights == NULL) || (information == NULL)) {
        return ADCS_E_NULL;
    }

    // Helper macro/inline block for zeroing and returning error
    // Since we can't define macros inside function easily without clutter, 
    // we will just write the logic inline or use a label/goto if allowed, 
    // but standard C allows goto. However, simple structure is preferred.

    // 2. Count range check [2, 32]
    if ((count < 2U) || (count > 32U)) {
        size_t r, c;
        for (r = 0; r < 3; r++)
            for (c = 0; c < 3; c++)
                information->m[r][c] = 0.0;
        return ADCS_E_RANGE;
    }

    // Local accumulator
    adcs_mat3_t h_acc = {{{0}}};
    adcs_vec3_t uk;
    adcs_mat3_t P, I, neg_P, Q, term;
    size_t i, r, c;

    // 3. Process each observation
    for (i = 0; i < count; i++) {
        // Check weight validity
        if ((!isfinite(weights[i])) || (weights[i] <= 0.0)) {
            for (r = 0; r < 3; r++)
                for (c = 0; c < 3; c++)
                    information->m[r][c] = 0.0;
            return ADCS_E_RANGE;
        }

        // Check vector finiteness
        if (!adcs_is_finite_vec3(&vectors[i])) {
            for (r = 0; r < 3; r++)
                for (c = 0; c < 3; c++)
                    information->m[r][c] = 0.0;
            return ADCS_E_RANGE;
        }

        // Normalize vector uk
        if (adcs_vec3_normalize(&vectors[i], ADCS_EPS_NORM, &uk) != ADCS_OK) {
            for (r = 0; r < 3; r++)
                for (c = 0; c < 3; c++)
                    information->m[r][c] = 0.0;
            return ADCS_E_RANGE; 
        }

        // Compute outer product P = uk * uk^T
        P = adcs_mat3_outer(&uk, &uk);

        // Compute Q = I - P
        I = adcs_mat3_identity();
        neg_P = adcs_mat3_scale(&P, -1.0);
        Q = adcs_mat3_add(&I, &neg_P);

        // Compute term = weight * Q
        term = adcs_mat3_scale(&Q, weights[i]);

        // Accumulate: h_acc += term
        h_acc = adcs_mat3_add(&h_acc, &term);
    }

    // Success: copy result to output
    *information = h_acc;

    return ADCS_OK;
}

