    size_t i;
    adcs_vec3_t u;
    double w;

    if ((vectors == NULL) || (weights == NULL) || (information == NULL)) {
        MatrixZero33((float64*)information->m);
        return ADCS_E_NULL;
    }

    if (count < 2U || count > 32U) {
        MatrixZero33((float64*)information->m);
        return ADCS_E_RANGE;
    }

    MatrixZero33((float64*)h.m);

    for (i = 0; i < count; i++) {
        w = weights[i];
        if (!isfinite(w) || w <= 0.0) {
            MatrixZero33((float64*)information->m);
            return ADCS_E_RANGE;
        }

        if (adcs_vec3_normalize(&vectors[i], FLT64_ZERO, &u) != ADCS_OK) {
            MatrixZero33((float64*)information->m);
            return ADCS_E_RANGE;
        }

        h.m[0][0] += w * (1.0 - u.x * u.x);
        h.m[0][1] += w * (-u.x * u.y);
        h.m[0][2] += w * (-u.x * u.z);
        h.m[1][0] += w * (-u.y * u.x);
        h.m[1][1] += w * (1.0 - u.y * u.y);
        h.m[1][2] += w * (-u.y * u.z);
        h.m[2][0] += w * (-u.z * u.x);
        h.m[2][1] += w * (-u.z * u.y);
        h.m[2][2] += w * (1.0 - u.z * u.z);
    }

    *information = h;
    return ADCS_OK;
}

